def solve(expr):
    def apply_op(operands, operators):
        right = operands.pop()
        left = operands.pop()
        op = operators.pop()
        if op == '+':
            operands.append(left + right)
        elif op == '-':
            operands.append(left - right)
        elif op == '*':
            operands.append(left * right)
        elif op == '/':
            operands.append(left // right)

    def greater_precedence(op1, op2):
        return (op1, op2) in [('+', '-'), ('*', '/')]

    def precedence(op):
        return {'+': 1, '-': 1, '*': 2, '/': 2}.get(op, 0)

    def parse_expression(expr):
        operands = []
        operators = []
        i = 0
        while i < len(expr):
            if expr[i].isdigit():
                num = 0
                while i < len(expr) and expr[i].isdigit():
                    num = num * 10 + int(expr[i])
                    i += 1
                operands.append(num)
                continue
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expr[i])):
                apply_op(operands, operators)
            operators.append(expr[i])
            i += 1
        while operators:
            apply_op(operands, operators)
        return operands[-1]

    return parse_expression(expr.replace(' ', ''))

# Test cases
